/** PRIME Brief: grounded current state plus executable next steps. */
public class PremiumHomeActivity extends Activity {
    VaultDb db;LinearLayout content;volatile int refreshGeneration=0;volatile boolean destroyed=false;final ExecutorService loader=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"cortex-prime-brief");t.setPriority(Thread.NORM_PRIORITY-1);return t;});
    int dp(int x){return CortexUi.dp(this,x);}
    @Override public void onCreate(Bundle b){super.onCreate(b);CortexUi.applyWindow(this);db=new VaultDb(getApplicationContext());CognitiveStore.ensure(db);CortexAttentionSchema.ensure(db);build();refreshAsync();}
    @Override protected void onResume(){super.onResume();if(!destroyed)refreshAsync();}
    @Override protected void onDestroy(){destroyed=true;refreshGeneration++;loader.shutdownNow();if(db!=null)try{db.close();}catch(Throwable ignored){}db=null;super.onDestroy();}

    void build(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(CortexUi.BG);ScrollView sv=new ScrollView(this);sv.setFillViewport(true);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(20),dp(14),dp(20),dp(26));sv.addView(content);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));header();briefControls();TextView loading=CortexUi.text(this,"Building your brief…",12,CortexUi.MUTED);loading.setPadding(0,dp(18),0,0);content.addView(loading);CortexUi.addBottomNav(this,root,"brief",null);setContentView(root);}
    void header(){LinearLayout head=new LinearLayout(this);head.setOrientation(LinearLayout.HORIZONTAL);head.setGravity(Gravity.CENTER_VERTICAL);LinearLayout titles=new LinearLayout(this);titles.setOrientation(LinearLayout.VERTICAL);TextView title=CortexUi.plain(this,"Brief",31,CortexUi.TEXT);CortexUi.medium(title);titles.addView(title);TextView subtitle=CortexUi.text(this,"What just happened, what needs you, and what Cortex thinks matters.",11,CortexUi.MUTED);subtitle.setPadding(0,dp(3),0,0);titles.addView(subtitle);head.addView(titles,new LinearLayout.LayoutParams(0,-2,1));TextView settings=CortexUi.chip(this,"Settings",CortexUi.MUTED,false);settings.setOnClickListener(v->open(SettingsActivity.class));head.addView(settings,new LinearLayout.LayoutParams(-2,dp(36)));content.addView(head);}
    void briefControls(){LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setPadding(0,dp(14),0,dp(2));TextView daily=CortexUi.action(this,"Daily brief",CortexUi.ACCENT,false),weekly=CortexUi.action(this,"Weekly brief",CortexUi.MUTED,false);daily.setOnClickListener(v->showComposed(false));weekly.setOnClickListener(v->showComposed(true));row.addView(daily,new LinearLayout.LayoutParams(0,dp(42),1));LinearLayout.LayoutParams wp=new LinearLayout.LayoutParams(0,dp(42),1);wp.setMargins(dp(8),0,0,0);row.addView(weekly,wp);content.addView(row);}

    void refreshAsync(){if(destroyed||loader.isShutdown())return;final int g=++refreshGeneration;try{loader.execute(()->{VaultDb local=null;try{local=new VaultDb(getApplicationContext());PrimeBriefStore.Snapshot s=PrimeBriefStore.load(local);postUi(()->{if(g==refreshGeneration)render(s);});}catch(Throwable e){postUi(()->{if(g==refreshGeneration)renderError();});}finally{if(local!=null)try{local.close();}catch(Throwable ignored){}}});}catch(RejectedExecutionException ignored){}}
    void showComposed(boolean weekly){if(destroyed||loader.isShutdown())return;try{loader.execute(()->{VaultDb local=null;try{local=new VaultDb(getApplicationContext());String text=BriefComposer.compose(local,weekly);postUi(()->briefDialog(text,weekly));}catch(Throwable e){postUi(()->Toast.makeText(this,"Could not build brief",Toast.LENGTH_SHORT).show());}finally{if(local!=null)try{local.close();}catch(Throwable ignored){}}});}catch(RejectedExecutionException ignored){}}
    void briefDialog(String text,boolean weekly){if(destroyed)return;Dialog d=new Dialog(this);ScrollView sv=new ScrollView(this);LinearLayout c=CortexUi.card(this,24);c.setPadding(dp(18),dp(18),dp(18),dp(18));sv.addView(c);TextView h=CortexUi.text(this,weekly?"Weekly Cortex Brief":"Daily Cortex Brief",21,CortexUi.TEXT);CortexUi.medium(h);c.addView(h);TextView b=CortexUi.text(this,text,13,CortexUi.TEXT);b.setPadding(0,dp(10),0,0);b.setTextIsSelectable(true);c.addView(b);TextView brain=CortexUi.action(this,"Ask Brain to analyze this brief",CortexUi.ACCENT,true);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(46));bp.setMargins(0,dp(14),0,0);c.addView(brain,bp);brain.setOnClickListener(v->{d.dismiss();CortexActionExecutor.openBrain(this,0,"Analyze my current "+(weekly?"weekly":"daily")+" Cortex brief. Prioritize what needs attention, identify connections or conflicts, and suggest the highest-leverage executable next steps.\n\n"+clip(text,5000));});TextView close=CortexUi.action(this,"Close",CortexUi.MUTED,false);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,dp(44));cp.setMargins(0,dp(8),0,0);c.addView(close,cp);close.setOnClickListener(v->d.dismiss());d.setContentView(sv);try{d.show();if(d.getWindow()!=null)d.getWindow().setLayout((int)(getResources().getDisplayMetrics().widthPixels*.94f),(int)(getResources().getDisplayMetrics().heightPixels*.84f));}catch(Throwable ignored){}}
    void postUi(Runnable r){if(destroyed||isFinishing()||isDestroyed())return;runOnUiThread(()->{if(!destroyed&&!isFinishing()&&!isDestroyed())try{r.run();}catch(Throwable ignored){}});}

    void render(PrimeBriefStore.Snapshot s){if(destroyed||content==null)return;while(content.getChildCount()>2)content.removeViewAt(2);if(s.empty()){LinearLayout empty=CortexUi.card(this,24);empty.setPadding(dp(18),dp(28),dp(18),dp(28));TextView h=CortexUi.plain(this,"Nothing needs you right now",19,CortexUi.TEXT);CortexUi.medium(h);empty.addView(h);TextView b=CortexUi.text(this,"New captures appear here while Cortex analyzes them, then grounded actions, waiting items, decisions and insights surface with source and reason.",12,CortexUi.MUTED);b.setPadding(0,dp(7),0,0);empty.addView(b);LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(-1,-2);ep.setMargins(0,dp(16),0,0);content.addView(empty,ep);return;}if(!s.attention.isEmpty()){content.addView(CortexUi.section(this,"Now"));for(int i=0;i<Math.min(3,s.attention.size());i++)attentionRow(s.attention.get(i));}if(!s.recent.isEmpty()){content.addView(CortexUi.section(this,"Recent"));for(int i=0;i<Math.min(6,s.recent.size());i++)recentRow(s.recent.get(i));}if(!s.actions.isEmpty()){content.addView(CortexUi.section(this,"Needs you"));for(int i=0;i<Math.min(6,s.actions.size());i++)derivedRow(s.actions.get(i));}if(!s.waiting.isEmpty()){content.addView(CortexUi.section(this,"Waiting"));for(int i=0;i<Math.min(5,s.waiting.size());i++)derivedRow(s.waiting.get(i));}if(!s.decisions.isEmpty()){content.addView(CortexUi.section(this,"Decisions"));for(int i=0;i<Math.min(5,s.decisions.size());i++)derivedRow(s.decisions.get(i));}if(!s.reviews.isEmpty()){content.addView(CortexUi.section(this,"Needs your review"));for(int i=0;i<Math.min(4,s.reviews.size());i++)reviewRow(s.reviews.get(i));TextView all=CortexUi.action(this,"Review all ("+s.reviews.size()+")",CortexUi.MUTED,false);all.setOnClickListener(v->open(ReviewQueueActivity.class));LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,dp(42));ap.setMargins(0,dp(8),0,0);content.addView(all,ap);}if(!s.worthKnowing.isEmpty()){content.addView(CortexUi.section(this,"Worth knowing"));for(int i=0;i<Math.min(6,s.worthKnowing.size());i++)derivedRow(s.worthKnowing.get(i));}if(!s.changes.isEmpty()){content.addView(CortexUi.section(this,"Changed & evolving"));for(int i=0;i<Math.min(6,s.changes.size());i++)derivedRow(s.changes.get(i));}}

    void attentionRow(AttentionFeedStore.Item x){LinearLayout card=CortexUi.card(this,20);card.setOrientation(LinearLayout.HORIZONTAL);card.setPadding(dp(12),dp(14),dp(12),dp(14));View bar=new View(this);bar.setBackgroundColor(CortexUi.ACCENT);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(dp(4),-1);bp.setMargins(0,0,dp(12),0);card.addView(bar,bp);LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);TextView badge=CortexUi.chip(this,"Needs attention",CortexUi.ACCENT,true);body.addView(badge,new LinearLayout.LayoutParams(-2,dp(28)));TextView title=CortexUi.text(this,x.title,15,CortexUi.TEXT);CortexUi.medium(title);title.setPadding(0,dp(8),0,0);body.addView(title);if(!empty(x.explanation)){TextView why=CortexUi.text(this,x.explanation,12,CortexUi.MUTED);why.setPadding(0,dp(5),0,0);why.setMaxLines(3);body.addView(why);}TextView meta=CortexUi.plain(this,x.subtitle+(x.sourceCount>1?"  •  "+x.sourceCount+" related signals":""),10,CortexUi.MUTED);meta.setPadding(0,dp(7),0,0);body.addView(meta);if(!empty(x.primaryAction)){TextView action=CortexUi.plain(this,x.primaryAction,11,CortexUi.ACCENT);action.setPadding(0,dp(7),0,0);body.addView(action);}card.addView(body,new LinearLayout.LayoutParams(0,-2,1));card.setOnClickListener(v->attentionDetail(x));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,dp(6),0,dp(6));content.addView(card,cp);}
    void attentionDetail(AttentionFeedStore.Item x){if(destroyed)return;OpenLoopStore.Loop loop=OpenLoopStore.get(db,x.entityId);Dialog d=new Dialog(this);ScrollView sv=new ScrollView(this);LinearLayout c=CortexUi.card(this,25);c.setPadding(dp(18),dp(18),dp(18),dp(18));sv.addView(c);TextView h=CortexUi.text(this,x.title,21,CortexUi.TEXT);CortexUi.medium(h);c.addView(h);TextView meta=CortexUi.plain(this,"Why this is here  •  confidence "+Math.round(x.confidence*100)+"%",10,CortexUi.MUTED);meta.setPadding(0,dp(5),0,dp(12));c.addView(meta);if(!empty(x.explanation))c.addView(CortexUi.text(this,x.explanation,13,CortexUi.TEXT));if(loop!=null&&loop.anchorSignalId>0){long evidenceId=RawSignalStore.promotedItemId(db,loop.anchorSignalId);if(evidenceId>0){TextView evidence=CortexUi.action(this,"Open source evidence",CortexUi.MUTED,false);LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(-1,dp(44));ep.setMargins(0,dp(14),0,0);c.addView(evidence,ep);evidence.setOnClickListener(v->{d.dismiss();try{Intent i=new Intent(this,VaultActivity.class);i.putExtra("item_id",evidenceId);startActivity(i);}catch(Throwable ignored){}});}}TextView brain=CortexUi.action(this,"Ask Brain for the best next action",CortexUi.ACCENT,true);LinearLayout.LayoutParams brp=new LinearLayout.LayoutParams(-1,dp(46));brp.setMargins(0,dp(12),0,0);c.addView(brain,brp);brain.setOnClickListener(v->{d.dismiss();CortexActionExecutor.openBrain(this,0,"This is a grounded Cortex attention item. Explain why it matters now and suggest an executable next step without inventing missing facts.\n\n"+x.title+"\n"+x.explanation);});TextView done=CortexUi.action(this,"Mark resolved",CortexUi.MUTED,false);LinearLayout.LayoutParams dpv=new LinearLayout.LayoutParams(-1,dp(44));dpv.setMargins(0,dp(8),0,0);c.addView(done,dpv);done.setOnClickListener(v->{if(OpenLoopStore.resolve(db,x.entityId,0,"resolved_by_user",1.0)){AttentionFeedStore.removeLoop(db,x.entityId);CognitiveStore.feedback(db,"open_loop",x.entityId,"resolved_by_user",new JSONObject().toString(),AttentionEngine.VERSION);d.dismiss();refreshAsync();}});TextView close=CortexUi.action(this,"Close",CortexUi.MUTED,false);LinearLayout.LayoutParams clp=new LinearLayout.LayoutParams(-1,dp(44));clp.setMargins(0,dp(8),0,0);c.addView(close,clp);close.setOnClickListener(v->d.dismiss());d.setContentView(sv);try{d.show();if(d.getWindow()!=null)d.getWindow().setLayout((int)(getResources().getDisplayMetrics().widthPixels*.94f),(int)(getResources().getDisplayMetrics().heightPixels*.82f));}catch(Throwable ignored){}}

    void recentRow(KnowledgeItem k){LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(dp(2),dp(12),dp(2),dp(12));CortexUi.pressable(this,row,CortexUi.round(this,Color.TRANSPARENT,Color.TRANSPARENT,12));LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);TextView title=CortexUi.text(this,empty(k.title)?friendlyType(k.type):k.title,14,CortexUi.TEXT);CortexUi.medium(title);top.addView(title,new LinearLayout.LayoutParams(0,-2,1));TextView badge=CortexUi.chip(this,recentStatus(k.status),statusColor(k.status),true);top.addView(badge,new LinearLayout.LayoutParams(-2,dp(30)));row.addView(top);String preview=!empty(k.summary)?k.summary:(!empty(k.extractedText)?k.extractedText:k.rawText);if(!empty(preview)){TextView p=CortexUi.text(this,clip(preview,160),12,CortexUi.MUTED);p.setMaxLines(3);p.setPadding(0,dp(5),0,0);row.addView(p);}TextView meta=CortexUi.plain(this,friendlyType(k.type)+"  •  "+age(k.createdAt)+"  •  captured by you",10,CortexUi.MUTED);meta.setPadding(0,dp(6),0,0);row.addView(meta);row.setOnClickListener(v->{if(destroyed)return;try{Intent i=new Intent(this,CaptureResultActivity.class);i.putExtra("item_id",k.id);startActivity(i);}catch(Throwable ignored){}});content.addView(row);content.addView(CortexUi.divider(this),new LinearLayout.LayoutParams(-1,dp(1)));}
    void derivedRow(PrimeBriefStore.Item x){LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(dp(2),dp(13),dp(2),dp(13));CortexUi.pressable(this,row,CortexUi.round(this,Color.TRANSPARENT,Color.TRANSPARENT,12));LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);TextView title=CortexUi.text(this,cleanTitle(x.title,x.kind),14,CortexUi.TEXT);CortexUi.medium(title);top.addView(title,new LinearLayout.LayoutParams(0,-2,1));TextView badge=CortexUi.chip(this,friendlyKind(x.kind),kindColor(x.kind),true);top.addView(badge,new LinearLayout.LayoutParams(-2,dp(30)));row.addView(top);String preview=cleanBody(x.body);if(!preview.isEmpty()){TextView body=CortexUi.text(this,clip(preview,180),12,CortexUi.MUTED);body.setPadding(0,dp(5),0,0);body.setMaxLines(3);row.addView(body);}TextView meta=CortexUi.plain(this,"Why: "+whyShort(x)+"  •  "+age(x.updatedAt),10,CortexUi.MUTED);meta.setPadding(0,dp(6),0,0);row.addView(meta);row.setOnClickListener(v->{if(!destroyed)derivedDetail(x);});content.addView(row);content.addView(CortexUi.divider(this),new LinearLayout.LayoutParams(-1,dp(1)));}
    void reviewRow(ReviewQueueStore.Item x){LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(dp(2),dp(13),dp(2),dp(13));CortexUi.pressable(this,row,CortexUi.round(this,Color.TRANSPARENT,Color.TRANSPARENT,12));TextView title=CortexUi.text(this,cleanTitle(x.title,x.candidateKind),14,CortexUi.TEXT);CortexUi.medium(title);row.addView(title);String body=cleanBody(x.body);if(!body.isEmpty()){TextView b=CortexUi.text(this,clip(body,180),12,CortexUi.MUTED);b.setPadding(0,dp(5),0,0);b.setMaxLines(3);row.addView(b);}TextView meta=CortexUi.plain(this,"Possible "+friendlyKind(x.candidateKind)+"  •  source "+sourceLabel(x.sourceKey)+"  •  "+age(x.createdAt),10,CortexUi.ACCENT);meta.setPadding(0,dp(6),0,0);row.addView(meta);row.setOnClickListener(v->open(ReviewQueueActivity.class));content.addView(row);content.addView(CortexUi.divider(this),new LinearLayout.LayoutParams(-1,dp(1)));}

    void derivedDetail(PrimeBriefStore.Item x){if(destroyed)return;Dialog d=new Dialog(this);ScrollView sv=new ScrollView(this);LinearLayout c=CortexUi.card(this,25);c.setPadding(dp(18),dp(18),dp(18),dp(18));sv.addView(c);TextView h=CortexUi.text(this,cleanTitle(x.title,x.kind),21,CortexUi.TEXT);CortexUi.medium(h);c.addView(h);TextView meta=CortexUi.plain(this,friendlyKind(x.kind)+"  •  "+sourceLabel(x.source)+"  •  "+exactTime(x.updatedAt),10,CortexUi.MUTED);meta.setPadding(0,dp(5),0,dp(12));c.addView(meta);if(!cleanBody(x.body).isEmpty()){TextView b=CortexUi.text(this,clip(cleanBody(x.body),12000),13,CortexUi.TEXT);b.setTextIsSelectable(true);c.addView(b);}TextView whyHead=CortexUi.section(this,"Why this is here");whyHead.setPadding(0,dp(14),0,dp(6));c.addView(whyHead);c.addView(CortexUi.text(this,whyLong(x),12,CortexUi.MUTED));TextView confidence=CortexUi.plain(this,"Confidence "+Math.round(x.confidence*100)+"%  •  priority "+x.importance,10,CortexUi.MUTED);confidence.setPadding(0,dp(10),0,0);c.addView(confidence);long evidenceId=sourceEvidenceId(x);TextView brain=CortexUi.action(this,"Ask Brain about this",CortexUi.ACCENT,true);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(46));bp.setMargins(0,dp(16),0,0);c.addView(brain,bp);brain.setOnClickListener(v->{d.dismiss();CortexActionExecutor.openBrain(this,evidenceId,"Use this grounded Brief item and its source evidence. Explain what it means, check it against my Cortex context, and suggest the most useful executable next step.\n\n"+cleanTitle(x.title,x.kind)+"\n"+clip(x.body,2000));});if(evidenceId>0){TextView evidence=CortexUi.action(this,"Open source evidence",CortexUi.MUTED,false);LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(-1,dp(44));ep.setMargins(0,dp(8),0,0);c.addView(evidence,ep);evidence.setOnClickListener(v->{d.dismiss();try{Intent i=new Intent(this,VaultActivity.class);i.putExtra("item_id",evidenceId);startActivity(i);}catch(Throwable ignored){}});}if("ACTION".equalsIgnoreCase(x.kind)||"WAITING".equalsIgnoreCase(x.kind)){TextView reminder=CortexUi.action(this,"Create reminder draft",CortexUi.MUTED,false);LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,dp(44));rp.setMargins(0,dp(8),0,0);c.addView(reminder,rp);reminder.setOnClickListener(v->CortexActionExecutor.calendarDraft(this,cleanTitle(x.title,x.kind),cleanBody(x.body),System.currentTimeMillis()+60L*60L*1000L));TextView done=CortexUi.action(this,"Mark resolved",CortexUi.MUTED,false);LinearLayout.LayoutParams dpv=new LinearLayout.LayoutParams(-1,dp(44));dpv.setMargins(0,dp(8),0,0);c.addView(done,dpv);done.setOnClickListener(v->{if(resolveDerived(x.id)){CognitiveStore.feedback(db,"derived",x.id,"resolved_by_user",new JSONObject().toString(),"brief_actions_001");d.dismiss();refreshAsync();}});}TextView close=CortexUi.action(this,"Close",CortexUi.MUTED,false);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,dp(44));cp.setMargins(0,dp(8),0,0);c.addView(close,cp);close.setOnClickListener(v->d.dismiss());d.setContentView(sv);try{d.show();if(d.getWindow()!=null)d.getWindow().setLayout((int)(getResources().getDisplayMetrics().widthPixels*.94f),(int)(getResources().getDisplayMetrics().heightPixels*.82f));}catch(Throwable ignored){}}
    long sourceEvidenceId(PrimeBriefStore.Item x){try{if(x.signalId>0){long id=RawSignalStore.promotedItemId(db,x.signalId);if(id>0)return id;}Cursor c=db.getReadableDatabase().rawQuery("SELECT from_id FROM source_links WHERE from_type='memory' AND to_type='derived' AND to_id=? ORDER BY created_at DESC LIMIT 1",new String[]{String.valueOf(x.id)});long id=c.moveToFirst()?c.getLong(0):0;c.close();return id;}catch(Throwable e){return 0;}}
    boolean resolveDerived(long id){try{ContentValues v=new ContentValues();v.put("state","resolved");v.put("updated_at",System.currentTimeMillis());return db.getWritableDatabase().update("derived_items",v,"id=?",new String[]{String.valueOf(id)})>0;}catch(Throwable e){return false;}}

    String whyShort(PrimeBriefStore.Item x){return friendlyKind(x.kind).toLowerCase(Locale.ROOT)+" from "+sourceLabel(x.source)+" · "+Math.round(x.confidence*100)+"%";}String whyLong(PrimeBriefStore.Item x){String role;if("ACTION".equalsIgnoreCase(x.kind))role="Cortex believes this is an open commitment that may need you.";else if("WAITING".equalsIgnoreCase(x.kind))role="Cortex believes someone or something may owe you a follow-up.";else if("DECISION".equalsIgnoreCase(x.kind))role="Cortex detected a decision worth keeping visible.";else role="Cortex considered this useful enough to keep in the Brief.";return role+" Source: "+sourceLabel(x.source)+". Confidence: "+Math.round(x.confidence*100)+"%.";}
    String recentStatus(String s){String x=n(s);if("analyzed".equals(x))return"Understood";if("analysis_failed".equals(x)||"failed_retryable".equals(x))return"Needs retry";return"Analyzing";}int statusColor(String s){return"analyzed".equals(n(s))?CortexUi.SAGE:("analysis_failed".equals(n(s))||"failed_retryable".equals(n(s))?CortexUi.ACCENT:CortexUi.MUTED);}String friendlyType(String t){if("AUDIO".equals(t))return"Voice";if("FILE".equals(t))return"File";if("SCREENSHOT".equals(t)||"IMAGE".equals(t))return"Image";return"Text";}void renderError(){if(destroyed||content==null)return;while(content.getChildCount()>2)content.removeViewAt(2);TextView t=CortexUi.text(this,"Brief could not load right now. Your data is still safe.",12,CortexUi.MUTED);t.setPadding(0,dp(24),0,0);content.addView(t);}void open(Class<?> c){if(destroyed)return;try{Intent i=new Intent(this,c);i.addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT|Intent.FLAG_ACTIVITY_SINGLE_TOP);startActivity(i);}catch(Throwable ignored){}}
    String friendlyKind(String k){String x=n(k).toUpperCase(Locale.ROOT);if("ACTION".equals(x))return"Action";if("WAITING".equals(x))return"Waiting";if("DECISION".equals(x))return"Decision";if("PROJECT_CANDIDATE".equals(x))return"Project";if("GOAL_SIGNAL".equals(x))return"Goal";if("IDEA".equals(x))return"Idea";if("OPPORTUNITY".equals(x))return"Opportunity";if("INSIGHT".equals(x))return"Insight";if("HYPOTHESIS".equals(x))return"Hypothesis";return x.isEmpty()?"Update":x;}int kindColor(String k){if("ACTION".equalsIgnoreCase(k))return CortexUi.ACCENT;if("WAITING".equalsIgnoreCase(k))return CortexUi.GOLD;if("DECISION".equalsIgnoreCase(k))return CortexUi.SAGE;if("OPPORTUNITY".equalsIgnoreCase(k)||"IDEA".equalsIgnoreCase(k)||"INSIGHT".equalsIgnoreCase(k))return CortexUi.SAGE;return CortexUi.MUTED;}
    String sourceLabel(String s){String x=n(s);if(x.isEmpty())return"Cortex";int p=x.lastIndexOf('.');if(p>=0&&p<x.length()-1)x=x.substring(p+1);x=x.replace('_',' ');return Character.toUpperCase(x.charAt(0))+x.substring(1);}String cleanTitle(String s,String kind){String x=n(s);if(x.isEmpty())return friendlyKind(kind);x=x.replace(" · Action","").replace(" · Waiting","").replace(" · Decision","").replace(" · Review action","").replace(" · Review waiting","").replace(" · Review decision","");return x.trim();}String cleanBody(String s){return n(s).replace("\n---\n","\n").trim();}String clip(String s,int max){String x=n(s);return x.length()<=max?x:x.substring(0,max)+"…";}String age(long ms){long m=Math.max(0,System.currentTimeMillis()-ms)/60000;if(m<1)return"now";if(m<60)return m+"m";long h=m/60;if(h<24)return h+"h";long d=h/24;return d<7?d+"d":new SimpleDateFormat("dd MMM",Locale.getDefault()).format(new Date(ms));}String exactTime(long ms){return new SimpleDateFormat("dd MMM · HH:mm",Locale.getDefault()).format(new Date(ms));}boolean empty(String s){return s==null||s.trim().isEmpty();}String n(String s){return s==null?"":s.trim();}
}
